import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { Link } from 'react-router-dom';
import './TransactionList.css';

const TransactionList = () => {
  console.log('TransactionList render start');
  const [transactions, setTransactions] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);

    // Determine API base URL.
    // In production (built Docker image) we set REACT_APP_API_URL (e.g., http://web:8000/farms).
    // During local development (CRA dev server) the browser cannot resolve Docker hostnames,
    // so we should use a relative path and let the proxy forward requests.
    const isProd = process.env.NODE_ENV === 'production';
    const API_BASE = isProd && process.env.REACT_APP_API_URL ? process.env.REACT_APP_API_URL : '';

    // Debug: log the computed API base and request URL
    console.log('TransactionList - isProd:', isProd, 'API_BASE:', API_BASE);

  useEffect(() => {
    const fetchTransactions = async () => {
      try {
        // Use environment variable for API URL when running in Docker
        const response = await axios.get(`${API_BASE}/api/transactions/`);
        console.log('Fetched transactions:', response.data);
        setTransactions(response.data);
        setLoading(false);
      } catch (err) {
        console.error('Error fetching transactions:', err);
        const msg = err.response?.data?.detail || err.message || 'Failed to fetch transactions';
        setError(msg);
        setLoading(false);
      }
    };

    fetchTransactions();
  }, []);

  const handleDelete = async (id) => {
    if (window.confirm('Are you sure you want to delete this transaction?')) {
      try {
        await axios.delete(`${API_BASE}/api/transactions/${id}/`);
        // Remove from local state
        setTransactions(transactions.filter(tx => tx.id !== id));
      } catch (err) {
        setError('Failed to delete transaction');
      }
    }
  };

  if (loading) return <div className="transaction-list-loading">Loading transactions...</div>;
  if (error) return <div className="transaction-list-error">{error}</div>;

  return (
    <div className="transaction-list">
      <h2>Transaction Management</h2>
      <Link to="/transactions/new" className="btn btn-primary">Add New Transaction</Link>

      <table className="transaction-table">
        <thead>
          <tr>
            <th>ID</th>
            <th>Memo</th>
            <th>Create Date</th>
            <th>Update Date</th>
            <th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {transactions.map(transaction => (
            <tr key={transaction.id}>
              <td>{transaction.id}</td>
              <td>{transaction.memo}</td>
              <td>{new Date(transaction.create_date).toLocaleDateString()}</td>
              <td>{new Date(transaction.update_date).toLocaleDateString()}</td>
              <td>
                <Link to={`/transactions/${transaction.id}/edit`} className="btn btn-secondary">Edit</Link>
                <button 
                  onClick={() => handleDelete(transaction.id)} 
                  className="btn btn-danger"
                >
                  Delete
                </button>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

export default TransactionList;
